-- ============================================================================
-- Тести знань: модуль «Як працює Грибний Радар» (app) — ADR-023
-- ============================================================================
-- Згенеровано scripts/quiz/build_module.py з data/quiz/app.json; читабельна версія — docs/quiz/app.md.
-- Питання оновлюються (за id), прибрані з JSON — знімаються з публікації; модуль публікується.

ON CONFLICT (id) DO UPDATE SET
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, correct = EXCLUDED.correct,
  explanation = EXCLUDED.explanation, source = EXCLUDED.source, critical = EXCLUDED.critical,
  topic = EXCLUDED.topic, published = true, hidden_by_reports = false, updated_at = now();

UPDATE public.quiz_questions SET published = false, updated_at = now()
WHERE module_id = 'app' AND id NOT IN ('app_level_high', 'app_odd_moon', 'app_tf_far_days', 'app_refresh', 'app_tf_poison', 'app_region', 'app_multi_up', 'app_photo', 'app_tf_unknown_public', 'app_edit', 'app_exact_place', 'app_tf_offset_avg', 'app_sixth', 'app_route_to_pick', 'app_share_public', 'app_public_level', 'app_grey', 'app_press_confirm', 'app_tf_marker', 'app_when_found', 'app_tf_no_points', 'app_lie_yes', 'app_points', 'app_tf_guest_public', 'app_order_trip', 'app_sos', 'app_tf_guardian_home', 'app_late', 'app_who_guardian', 'app_lost', 'app_odd_offline', 'app_ai_next', 'app_tf_ai_server', 'app_twins_where', 'app_ai_shots', 'app_ai_not_mushroom', 'app_ai_poison_twin', 'app_tf_ai_history', 'app_catalog_offline');

UPDATE public.quiz_modules SET published = true, questions_per_attempt = 15 WHERE id = 'app';
