INSERT INTO public.quiz_questions (id, module_id, kind, prompt, options, correct, explanation, source, critical, topic) VALUES
  ('app_level_high', 'app', 'single', 'Прогноз показує «висока» для лисички на завтра. Що це означає?', '[{"id": "a", "text": "Лисички точно будуть"}, {"id": "b", "text": "Умови для лисичок добрі"}, {"id": "c", "text": "Лисички вже виросли"}, {"id": "d", "text": "Гриби можна не перевіряти"}]'::jsonb, '["b"]'::jsonb, 'Прогноз оцінює умови: погоду, ліс, сезон. «Висока» — умови добрі, але знахідку ніхто не гарантує, а кожен гриб треба перевіряти.', 'ADR-015; екран прогнозу ділянки', false, 'forecast'),
  ('app_odd_moon', 'app', 'single', 'Що з цього НЕ впливає на прогноз ділянки?', '[{"id": "a", "text": "Дощі за минулий тиждень"}, {"id": "b", "text": "Які дерева на ділянці"}, {"id": "c", "text": "Фаза Місяця"}, {"id": "d", "text": "Сезон гриба"}]'::jsonb, '["c"]'::jsonb, 'Прогноз рахує погоду з запізненням, ліс ділянки й сезон виду. Місяць у розрахунку немає.', 'ADR-015; supabase/functions/_shared/forecast/', false, 'forecast'),
  ('app_tf_far_days', 'app', 'single', 'Правда чи міф: прогноз на 7-й день такий самий точний, як на завтра.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Що далі день, то менш точний прогноз погоди, а з ним — і прогноз грибів. Тому далекі дні позначені «орієнтовно».', 'analysis.ts (approximate_label)', false, 'forecast'),
  ('app_refresh', 'app', 'single', 'Учора ви створили ділянку. Сьогодні хочете свіжий прогноз. Що зробити?', '[{"id": "a", "text": "Створити ділянку заново"}, {"id": "b", "text": "«Оновити аналіз»"}, {"id": "c", "text": "Почекати до неділі"}, {"id": "d", "text": "Додати ще одну ділянку"}]'::jsonb, '["b"]'::jsonb, 'Ділянку не треба перестворювати: «Оновити аналіз» раз на добу — безкоштовно, а погода підтягується кожні 3 години.', 'ADR-015; analysis.ts (daily refresh)', false, 'forecast'),
  ('app_tf_poison', 'app', 'single', 'Правда чи міф: якщо прогноз не показує бліду поганку, у лісі її зараз немає.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Прогноз навмисно показує лише їстівні гриби. Отруйні ростуть у ті самі дні — тому кожен гриб перевіряйте за ознаками.', 'B2.4 (forecast/db.ts)', false, 'forecast'),
  ('app_region', 'app', 'single', 'Чи можна зробити прогноз ділянки в сусідній області?', '[{"id": "a", "text": "Так, будь-де в Україні"}, {"id": "b", "text": "Ні, лише у своїй області"}, {"id": "c", "text": "Так, якщо поруч з кордоном"}, {"id": "d", "text": "Так, після першого походу"}]'::jsonb, '["b"]'::jsonb, 'Ділянки — лише у вашій області: для неї застосунок тримає ліси й карту без інтернету.', 'ADR-015 §15.2', false, 'forecast'),
  ('app_multi_up', 'app', 'multi', 'Що може підняти прогноз гриба на вашій ділянці? Оберіть усе правильне.', '[{"id": "a", "text": "Тепло після доброго дощу"}, {"id": "b", "text": "Підтверджені знахідки поруч"}, {"id": "c", "text": "Ви часто відкриваєте прогноз"}, {"id": "d", "text": "Чужі приватні точки поруч"}]'::jsonb, '["a", "b"]'::jsonb, 'Прогноз піднімають погода й підтверджені знахідки того самого гриба в радіусі 10 км за тиждень. Приватні точки ніхто не перевіряє, а скільки разів ви відкриваєте прогноз — не важливо.', 'ADR-015; forecast/crowd.ts', false, 'forecast'),
  ('app_photo', 'app', 'single', 'Як додати фото до тук-тука?', '[{"id": "a", "text": "Вибрати з галереї"}, {"id": "b", "text": "Камерою в застосунку"}, {"id": "c", "text": "Переслати з месенджера"}, {"id": "d", "text": "Будь-яким із цих способів"}]'::jsonb, '["b"]'::jsonb, 'Лише камерою застосунку: так точка показує місце й час, де гриб справді знайшли.', 'ADR-018 §18.3', false, 'picks'),
  ('app_tf_unknown_public', 'app', 'single', 'Правда чи міф: точку «Не знаю, що це» можна зробити публічною.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Публічна точка — лише з видом із довідника. «Не знаю» — тільки для себе, щоб не вводити інших в оману.', 'ADR-018; can_create_pick / update_pick (species_required)', false, 'picks'),
  ('app_edit', 'app', 'multi', 'Що можна змінити у своїй точці після збереження? Оберіть усе правильне.', '[{"id": "a", "text": "Опис"}, {"id": "b", "text": "Хто бачить точку"}, {"id": "c", "text": "Фото"}, {"id": "d", "text": "Вид гриба"}]'::jsonb, '["a", "b"]'::jsonb, 'У картці своєї точки: «Змінити опис», «Зробити публічною / приватною», «Видалити точку». Фото й вид не змінюються — це свідчення того, що ви знайшли.', 'B3.4 (update_pick)', false, 'picks'),
  ('app_exact_place', 'app', 'single', 'Хто бачить точне місце вашої публічної точки?', '[{"id": "a", "text": "Усі в області"}, {"id": "b", "text": "Лише ваші друзі"}, {"id": "c", "text": "Лише ви"}, {"id": "d", "text": "Лише Наглядач"}]'::jsonb, '["c"]'::jsonb, 'Іншим публічну точку показують зі зсувом 300–500 м. Точне місце — лише у вас.', 'ADR-018 §18.5', false, 'picks'),
  ('app_tf_offset_avg', 'app', 'single', 'Правда чи міф: якщо відкрити чужу точку багато разів, вона покаже точніше місце.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Зсув для кожної точки постійний — скільки не відкривай, місце те саме.', 'picks/fuzz.ts', false, 'picks'),
  ('app_sixth', 'app', 'single', 'У вас 5 приватних точок, а хочете ще одну. Що зробити?', '[{"id": "a", "text": "Почекати до завтра"}, {"id": "b", "text": "Видалити одну стару"}, {"id": "c", "text": "Перезняти фото точки"}, {"id": "d", "text": "Вийти й увійти знову"}]'::jsonb, '["b"]'::jsonb, 'Приватних точок без Pro — до 5 одночасно. Ліміт не на день, а на кількість: видаліть стару — з''явиться місце.', 'ADR-019 §19.10', false, 'picks'),
  ('app_route_to_pick', 'app', 'single', 'Як найшвидше прокласти маршрут до своєї точки?', '[{"id": "a", "text": "«Відкрити в Google Картах»"}, {"id": "b", "text": "Зробити точку публічною"}, {"id": "c", "text": "Скопіювати опис точки в нотатки"}, {"id": "d", "text": "Попросити Наглядача про маршрут"}]'::jsonb, '["a"]'::jsonb, 'У картці своєї точки є «Відкрити в Google Картах» — там маршрут до точного місця.', 'B3.4c (#156)', false, 'picks'),
  ('app_share_public', 'app', 'single', 'Хочете, щоб точку бачили інші грибники. Що обрати під час збереження?', '[{"id": "a", "text": "«Лише я»"}, {"id": "b", "text": "«Усі»"}, {"id": "c", "text": "«Не знаю, що це»"}, {"id": "d", "text": "«Перезняти»"}]'::jsonb, '["b"]'::jsonb, '«Хто бачить точку» → «Усі». Публічні точки доступні з рівня «Лісовик».', 'екран «Новий тук-тук»; ADR-019 §19.10', false, 'picks'),
  ('app_public_level', 'app', 'single', 'Що потрібно, щоб ставити публічні точки?', '[{"id": "a", "text": "Пройти всі тести"}, {"id": "b", "text": "Рівень «Лісовик»"}, {"id": "c", "text": "Мати 5 приватних точок"}, {"id": "d", "text": "Увімкнути Наглядача"}]'::jsonb, '["b"]'::jsonb, 'Публічні точки — з рівня «Лісовик» (201+ балів). Новачки ставлять приватні точки для себе.', 'ADR-013; ADR-019 §19.10', false, 'picks'),
  ('app_grey', 'app', 'single', 'Чому чужа точка на карті сіра?', '[{"id": "a", "text": "Ще ніхто не підтвердив"}, {"id": "b", "text": "Їй уже більше тижня"}, {"id": "c", "text": "Гриб на ній отруйний"}, {"id": "d", "text": "Автор має низький рівень"}]'::jsonb, '["a"]'::jsonb, 'Сіра — «Перевіряється»: точку ще не підтвердив інший грибник своєю знахідкою.', 'ADR-019 §19.5', false, 'community'),
  ('app_press_confirm', 'app', 'single', 'Біля чужої сірої точки білого ви теж знайшли білий. Що натиснути, щоб допомогти іншим?', '[{"id": "a", "text": "«Знайшли?»"}, {"id": "b", "text": "«Я теж знайшов тут»"}, {"id": "c", "text": "«Відкрити в Google Картах»"}, {"id": "d", "text": "«Видалити точку»"}]'::jsonb, '["b"]'::jsonb, '«Я теж знайшов тут» у картці чужої точки: знімаєте свою знахідку — і точка може стати підтвердженою.', 'B3.8b (#163)', false, 'community'),
  ('app_tf_marker', 'app', 'single', 'Правда чи міф: щоб підтвердити чужу точку, достатньо дійти до позначки на карті.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Позначка зсунута на 300–500 м. Підтверджує лише своя знахідка того самого гриба до 200 м від справжнього місця.', 'ADR-019 §19.5; B3.8a', false, 'community'),
  ('app_when_found', 'app', 'single', 'Коли застосунок питає «Знайшли гриби?»', '[{"id": "a", "text": "Щоранку в сезон"}, {"id": "b", "text": "Після кожного прогнозу"}, {"id": "c", "text": "Після «Я вдома»"}, {"id": "d", "text": "Коли відкриваєте карту"}]'::jsonb, '["c"]'::jsonb, 'Питання з''являється після «Я вдома», якщо похід був біля вашої ділянки прогнозу або з Наглядачем.', 'B3.11 (#155)', false, 'community'),
  ('app_tf_no_points', 'app', 'single', 'Правда чи міф: за чесне «Ні» на «Знайшли гриби?» теж дають бали.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Так: бали дають за чесний відгук — і за «Так», і за «Ні» (раз на добу, через добу після відповіді). Застосунку потрібна правда, а не лише вдалі походи.', 'ADR-014; B3.11', false, 'community'),
  ('app_lie_yes', 'app', 'single', 'Ви нічого не знайшли, але відповіли «Так». Кому це зашкодить найбільше?', '[{"id": "a", "text": "Нікому"}, {"id": "b", "text": "Іншим грибникам"}, {"id": "c", "text": "Вам самим"}, {"id": "d", "text": "Застосунку"}]'::jsonb, '["c"]'::jsonb, 'Відгуки показують, як часто прогноз збувається саме для вас, і допомагають налаштувати прогноз вашої області. Неправда псує це для вас.', 'ADR-014 §14.1', false, 'community'),
  ('app_points', 'app', 'multi', 'За що дають бали? Оберіть усе правильне.', '[{"id": "a", "text": "Пройдений модуль тесту"}, {"id": "b", "text": "Підтвердження чужої точки"}, {"id": "c", "text": "Розпізнавання гриба ШІ"}, {"id": "d", "text": "Щоденний вхід у застосунок"}]'::jsonb, '["a", "b"]'::jsonb, 'Бали — за знання й реальну активність у лісі. За розпізнавання й просто відкриття застосунку їх не дають.', 'ADR-012', false, 'community'),
  ('app_tf_guest_public', 'app', 'single', 'Правда чи міф: гість без входу може ставити приватні точки.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Так: гість має прогноз, карту, приватні точки, ШІ й безпеку. Публічні точки, друзі, Наглядач і бали — після входу через Google або Apple.', 'ADR-001; can_create_pick', false, 'community'),
  ('app_order_trip', 'app', 'order', 'Ви їдете в ліс, де немає зв''язку. Розставте дії по порядку.', '[{"id": "a", "text": "Удома завантажити офлайн-карту"}, {"id": "b", "text": "Біля машини натиснути «Старт тут»"}, {"id": "c", "text": "Натиснути «Почати похід»"}, {"id": "d", "text": "У лісі повернутися «Додому»"}]'::jsonb, '["a", "b", "c", "d"]'::jsonb, 'Без зв''язку працює лише те, що вже на телефоні. Карту — заздалегідь, маршрут і похід — до того, як зникне зв''язок.', 'ADR-020; вкладка «Безпека»', false, 'safety'),
  ('app_sos', 'app', 'single', 'Як увімкнути SOS?', '[{"id": "a", "text": "Натиснути двічі поспіль"}, {"id": "b", "text": "Утримати 3 секунди"}, {"id": "c", "text": "Потрусити телефон"}, {"id": "d", "text": "Сказати вголос «SOS»"}]'::jsonb, '["b"]'::jsonb, 'Кнопку SOS треба утримати 3 секунди — щоб не натиснути випадково. Тоді сирена, координати й дзвінок 112.', 'safety_screen.dart', false, 'safety'),
  ('app_tf_guardian_home', 'app', 'single', 'Правда чи міф: після «Я вдома» трек вашого походу видаляється з сервера.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Так: Наглядач бачить, де ви, лише під час походу. Після «Я вдома» трек на сервері видаляється.', 'ADR-022', false, 'safety'),
  ('app_late', 'app', 'single', 'Ви не повернулися до обіцяного часу. Що станеться спершу?', '[{"id": "a", "text": "Одразу подзвонить на 112"}, {"id": "b", "text": "Спитає вас «Все добре?»"}, {"id": "c", "text": "Наглядач одразу отримає тривогу"}, {"id": "d", "text": "Похід завершиться сам"}]'::jsonb, '["b"]'::jsonb, 'Спершу застосунок питає вас «Все добре?». Якщо не відповісте — тривогу отримає Наглядач.', 'ADR-022; guardian.ts (check → alert)', false, 'safety'),
  ('app_who_guardian', 'app', 'single', 'Хто може бути вашим Наглядачем?', '[{"id": "a", "text": "Будь-хто за посиланням"}, {"id": "b", "text": "Друг у застосунку"}, {"id": "c", "text": "Будь-хто з контактів"}, {"id": "d", "text": "Рятувальна служба"}]'::jsonb, '["b"]'::jsonb, 'Лише друг у застосунку, якому ви довіряєте: ваше місце в лісі — чутлива інформація.', 'ADR-022', false, 'safety'),
  ('app_lost', 'app', 'single', 'Ви в лісі без зв''язку й не знаєте, куди йти. Що допоможе вийти до машини?', '[{"id": "a", "text": "Чекати, доки з''явиться зв''язок"}, {"id": "b", "text": "Кнопка «Додому»"}, {"id": "c", "text": "Йти до найближчої точки"}, {"id": "d", "text": "Google Карти"}]'::jsonb, '["b"]'::jsonb, '«Додому» веде слідом, стежками чи прямо компасом — без інтернету, якщо похід почали з «Старт тут».', 'вкладка «Безпека» (похід, «Додому»)', false, 'safety'),
  ('app_odd_offline', 'app', 'single', 'Що з цього НЕ працює без інтернету, навіть якщо все завантажено?', '[{"id": "a", "text": "Завантажена карта області"}, {"id": "b", "text": "Розпізнавання гриба"}, {"id": "c", "text": "Компас і «Додому»"}, {"id": "d", "text": "Новий прогноз ділянки"}]'::jsonb, '["d"]'::jsonb, 'Карта, ШІ й «Додому» працюють з телефона. Новий прогноз рахує сервер — для нього потрібен інтернет.', 'ADR-020; ADR-006; ADR-015', false, 'safety'),
  ('app_ai_next', 'app', 'single', 'ШІ підказує: «Схоже на лисичку». Що робити далі?', '[{"id": "a", "text": "Сміливо готувати"}, {"id": "b", "text": "Звірити в довіднику"}, {"id": "c", "text": "Перезняти, доки не буде 100 %"}, {"id": "d", "text": "Одразу поставити точку"}]'::jsonb, '["b"]'::jsonb, 'ШІ — лише підказка, з якого виду почати перевірку. Звірте ознаки й двійників у довіднику.', 'ADR-006', false, 'recognition'),
  ('app_tf_ai_server', 'app', 'single', 'Правда чи міф: ШІ розпізнає гриб і там, де немає зв''язку.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Так: модель працює прямо на телефоні, фото нікуди не надсилається. Тільки завантажте ШІ вдома заздалегідь.', 'ADR-006; ADR-020', false, 'recognition'),
  ('app_twins_where', 'app', 'single', 'Де подивитися, чим білий гриб відрізняється від жовчного?', '[{"id": "a", "text": "У довіднику"}, {"id": "b", "text": "На карті точок"}, {"id": "c", "text": "У налаштуваннях профілю"}, {"id": "d", "text": "У списку друзів"}]'::jsonb, '["a"]'::jsonb, 'У довіднику біля виду є «Як відрізнити» — ознаки й небезпечні двійники. Те саме відкривається з картки гриба в прогнозі та з результату ШІ.', 'довідник («Як відрізнити»)', false, 'recognition'),
  ('app_ai_shots', 'app', 'order', 'ШІ просить три кадри одного гриба. Розставте їх по порядку.', '[{"id": "a", "text": "Шапка зверху або збоку"}, {"id": "b", "text": "Ніжка збоку цілком"}, {"id": "c", "text": "Зріз або низ шапки зблизька"}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Застосунок веде за кроками: спершу шапка, потім уся ніжка, наостанок зріз або низ шапки. Три кадри з різних боків — і ШІ помиляється рідше.', 'екран «Розпізнати» (кроки «Шапка», «Ніжка», «Зріз»)', false, 'recognition'),
  ('app_ai_not_mushroom', 'app', 'single', 'ШІ пише «Це не схоже на гриб», а це точно гриб. Що зробити?', '[{"id": "a", "text": "Перезняти ближче до шапки"}, {"id": "b", "text": "Чекати, поки з''явиться зв''язок"}, {"id": "c", "text": "Оновити застосунок"}, {"id": "d", "text": "Поставити точку «Не знаю»"}]'::jsonb, '["a"]'::jsonb, 'Найчастіше гриб займає замало кадру. Підійдіть ближче, щоб шапка була великою, і натисніть «Перезняти». Зв''язок для ШІ не потрібен.', 'екран результату («Хм… Це не схоже на гриб», «Перезняти»)', false, 'recognition'),
  ('app_ai_poison_twin', 'app', 'single', 'ШІ попереджає: «Серед схожих є отруйний гриб». Що це означає?', '[{"id": "a", "text": "Ваш гриб точно отруйний"}, {"id": "b", "text": "Можна сплутати з отруйним"}, {"id": "c", "text": "ШІ помилився з фото"}, {"id": "d", "text": "Його можна їсти після варіння"}]'::jsonb, '["b"]'::jsonb, 'Попередження означає: серед схожих видів є отруйний двійник. Ваш гриб не обов''язково отруйний — відкрийте «Як відрізнити» і звірте ознаки. Якщо сумніваєтеся — не їжте.', 'екран результату розпізнавання', false, 'recognition'),
  ('app_tf_ai_history', 'app', 'single', 'Правда чи міф: історія ваших розпізнавань зберігається лише на вашому телефоні.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Так: і фото, і історія розпізнавань лишаються на телефоні. Очистити її можна будь-коли кнопкою «Очистити».', 'екран «Історія розпізнавань»; ADR-006', false, 'recognition'),
  ('app_catalog_offline', 'app', 'single', 'У лісі немає зв''язку, а ви хочете гортати довідник з фото. Що зробити вдома?', '[{"id": "a", "text": "Зробити знімки екрана"}, {"id": "b", "text": "«Фото без інтернету»"}, {"id": "c", "text": "Нічого, фото вже є"}, {"id": "d", "text": "Увімкнути режим польоту"}]'::jsonb, '["b"]'::jsonb, 'Фото грибів треба зберегти заздалегідь: у довіднику «Фото без інтернету» → «Завантажити», краще через Wi‑Fi. Тоді довідник працює в лісі без зв''язку.', 'довідник («Фото без інтернету»)', false, 'recognition')
